def test_current_exports_remain_canonical():
    for package, contract in CONTRACTS.items():
        module = importlib.import_module(package)
        assert module.__all__ == contract['exports']
        if contract['version'] is not None:
            assert module.__version__ == contract['version']
        for name in contract['exports']:
            if name == '__version__':
                continue
            origin, attribute = contract['mapping'][name]
            expected = getattr(importlib.import_module(origin, package), attribute)
            actual = getattr(module, name)
            assert actual is expected, (package, name)
            if inspect.isclass(actual) or inspect.isfunction(actual):
                assert pickle.loads(pickle.dumps(actual)) is actual
        assert set(contract['exports']) <= set(dir(module))
        assert set(contract['exports']) <= dict(inspect.getmembers(module)).keys()
        for name in contract['modules']:
            assert getattr(module, name) is importlib.import_module('.'+name, package)
        scope = {}
        exec('from '+package+' import *', scope)
        assert all(scope[name] is getattr(module,name) for name in contract['exports'])


def test_cold_worker_and_construction_import_orders():
    cases = [
        "import anyfem.job_process; import sys; assert 'anyfem.application' not in sys.modules; assert 'anyfem.solve' not in sys.modules",
        "from anyfem.geometry.construction import ConstructionTask; from anyfem import Project; assert Project('cold').geometry is not None",
        "from anyfem.commands import AddPoint; from anyfem import Project; from anyfem.geometry import ConstructionTask",
    ]
    for source in cases:
        result = subprocess.run([sys.executable,'-B','-c',source],capture_output=True,text=True,timeout=30)
        assert result.returncode == 0, result.stderr


BASELINE_MODULES = {'anyfem': ['application', 'commands', 'document', 'geometry', 'geometry_features', 'io', 'job_process', 'jobs', 'mesh', 'mesh_controls', 'mesh_jobs', 'mesh_numbering', 'model', 'native_meshing', 'native_meshing_backend', 'post', 'scripting', 'selection', 'sketcher', 'solve', 'structural_preparation'], 'anyfem.geometry': ['construction', 'curves', 'entities', 'model', 'operations', 'sketching', 'snapping', 'surfaces']}

def test_prior_eager_module_attributes_remain_public():
    for package, names in BASELINE_MODULES.items():
        module = importlib.import_module(package)
        assert set(names) <= set(dir(module))
        for name in names:
            assert getattr(module, name) is importlib.import_module('.'+name, package)
